/**
 * The style's surfaces: Slate and Sea by day, the [night] background's by night (each style has its own blue-grey and graphite);
 * null = the default Telegram look. (Dynamic colours drop all of them in the caller.)
 */
internal fun neutralsOf(style: TatrakStyle, dark: Boolean, night: NightBackground): Neutrals? =
    when {
        !dark -> if (style == TatrakStyle.SLATE_SEA) slateDay else null
        style == TatrakStyle.SLATE_SEA ->
            when (night) {
                NightBackground.BLUE_GREY -> slateNight
                NightBackground.GRAPHITE -> slateGraphiteNight
                NightBackground.AMOLED -> slateAmoledNight
            }
        else ->
            when (night) {
                NightBackground.BLUE_GREY -> null
                NightBackground.GRAPHITE -> graphiteNight
                NightBackground.AMOLED -> amoledNight
            }
    }

